using System.Security.Cryptography;
using UnscRelay.Core;
internal static class PublicKeyInstallationChecks
{
 public static async Task<int> Run(ConnectionProfile endpoint,string root,string local){
  var passed=0;void Check(bool value,string name){if(!value)throw new Exception(name);Console.WriteLine("PASS key install: "+name);passed++;}var ct=CancellationToken.None;var profile=endpoint with{Username="install-test"};var hosts=new HostKeyStore(Path.Combine(local,"install-hosts.json"));using var source=new SshSession(profile,"relay-test-password",null,"",hosts,_=>true,_=>throw new Exception("Unexpected interaction"));await source.ConnectAsync(100,30);
  using var vault=new KeyVault(Path.Combine(local,"install-vault.json"));vault.Unlock("Synthetic installer vault password");var key=KeyGeneration.Generate(vault,"Synthetic installation key","ed25519");var privateKey=vault.Read(key.Id);var probeProfile=profile with{Protocol="ssh",Authentication="key",KeyId=key.Id,KeyboardFallback=false};
  async Task Probe(HostKeyStore? pins=null){using var probe=new SshSession(probeProfile,"",privateKey,"",pins??hosts,_=>false,_=>throw new Exception("No interactive fallback"));await probe.VerifyKeyAuthenticationAsync(ct);}
  try{
   try{await Probe();throw new Exception("Uninstalled key accepted");}catch(Renci.SshNet.Common.SshAuthenticationException){Check(true,"new key is refused before installation");}
   Check(SftpPermissions.Parse("0640")==640&&SftpPermissions.FromLegacyBits(416)==640,"octal UI permissions and legacy queue bits preserve the intended mode");
   var preview=await source.PreparePublicKeyInstallationAsync(key.PublicKey);Check(!preview.FileExists&&!preview.DirectoryExists&&!preview.AlreadyPresent,"preview describes new standard authorized_keys without writing it");Check(!File.Exists(Path.Combine(root,".ssh","authorized_keys")),"preview performs no remote configuration write");var installed=await source.InstallPublicKeyAsync(preview);var path=Path.Combine(root,".ssh","authorized_keys");Check(installed.DirectoryCreated&&File.ReadAllText(path).Contains(key.PublicKey,StringComparison.Ordinal)&&!File.ReadAllText(path).Contains("PRIVATE KEY",StringComparison.Ordinal),"only the public key is installed in the standard directory");
   File.WriteAllText(Path.Combine(root,"install-auth.log"),"");File.WriteAllText(Path.Combine(root,"install-channels.log"),"");await Probe();Check(File.ReadAllLines(Path.Combine(root,"install-auth.log")).SequenceEqual(new[]{"publickey"}),"verification uses only the selected private key without password fallback");Check(File.ReadAllText(Path.Combine(root,"install-channels.log"))=="","verification opens no shell, SFTP subsystem or command channel");
   using(var password=new SshSession(profile,"relay-test-password",null,"",hosts,_=>false,_=>throw new Exception("Unexpected interaction"))){await password.ConnectAsync(100,30);Check(password.FilesAvailable,"the previous password access remains usable");}
   var original=File.ReadAllBytes(path);var duplicate=await source.PreparePublicKeyInstallationAsync(key.PublicKey);await source.InstallPublicKeyAsync(duplicate);Check(duplicate.AlreadyPresent&&File.ReadAllBytes(path).SequenceEqual(original),"an installed key is not appended again");
   File.WriteAllText(path,"from=\"192.0.2.1\" "+key.PublicKey+" restricted\n");var restricted=await source.PreparePublicKeyInstallationAsync(key.PublicKey);var restriction=File.ReadAllBytes(path);await source.InstallPublicKeyAsync(restricted);Check(restricted.AlreadyPresent&&File.ReadAllBytes(path).SequenceEqual(restriction),"existing restricted key is never duplicated without its restrictions");
   File.WriteAllText(path,"# synthetic original\n");var stale=await source.PreparePublicKeyInstallationAsync(key.PublicKey);File.AppendAllText(path,"# concurrent change\n");try{await source.InstallPublicKeyAsync(stale);throw new Exception("Stale preview accepted");}catch(IOException){Check(!File.ReadAllText(path).Contains(key.PublicKey,StringComparison.Ordinal),"changed authorized_keys refuses stale installation without losing concurrent lines");}
   await source.FileOperationAsync("chmod","/.ssh","777");try{await source.PreparePublicKeyInstallationAsync(key.PublicKey);throw new Exception("Unsafe directory accepted");}catch(IOException){Check(true,"writable-by-others SSH directory is refused");}await source.FileOperationAsync("chmod","/.ssh","700");
   File.WriteAllText(Path.Combine(root,"install-auth.log"),"");try{await Probe(new HostKeyStore(Path.Combine(local,"unknown-install-hosts.json")));throw new Exception("Unknown host accepted");}catch(Renci.SshNet.Common.SshConnectionException){Check(File.ReadAllText(Path.Combine(root,"install-auth.log"))=="","verification refuses unknown host before authentication");}
   using(var fallback=new SshSession(probeProfile with{Authentication="auto"},"",privateKey,"",hosts,_=>false,_=>"")){try{await fallback.VerifyKeyAuthenticationAsync();throw new Exception("Fallback probe accepted");}catch(InvalidOperationException){Check(true,"verification rejects an authentication profile that permits fallback");}}
   var cancelled=new CancellationToken(true);try{await source.PreparePublicKeyInstallationAsync(key.PublicKey,cancelled);throw new Exception("Cancelled operation accepted");}catch(OperationCanceledException){Check(true,"cancelled preview performs no configuration write");}
  }finally{CryptographicOperations.ZeroMemory(privateKey);}return passed;
 }
}
